function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),2600)}
function xp(){return state.logs.reduce((n,l)=>n+(+l.minutes||0),0)+state.days.flatMap(d=>d.tasks||[]).filter(t=>t.done).length*15+state.errors.length*5}
function streak(){const dates=new Set(state.logs.map(x=>x.date));let n=0,d=new Date();if(!dates.has(today()))d.setDate(d.getDate()-1);while(dates.has(fmtDate(d))){n++;d.setDate(d.getDate()-1)}return n}
function fmtDate(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
