async function saveState(){state.updatedAt=new Date().toISOString();const {error}=await supabase.from('study_data').upsert({user_id:user.id,data:state,updated_at:state.updatedAt},{onConflict:'user_id'});if(error){console.error(error);toast('Could not save: '+error.message);return false}const xpUpdate=await supabase.from('profiles').update({xp:xp()}).eq('id',user.id);if(xpUpdate.error){console.error(xpUpdate.error);toast('Study data saved, but ranking XP did not sync.')}else if(profile)profile.xp=xp();updateHeader();return true}
async function loadState(){const {data,error}=await supabase.from('study_data').select('data').eq('user_id',user.id).maybeSingle();if(error)throw error;if(data?.data){state={...defaultState(),...data.data};state.schedules={...defaultState().schedules,...(data.data.schedules||{})};state.logs=(state.logs||[]).map(l=>({...l,questionsSolved:Number(l.questionsSolved)||0,questionsCorrect:Number(l.questionsCorrect)||0,focus:l.focusRated===true?(Number(l.focus)||0):0}));}else await saveState()}
