let authLoadId=0,timerPersistAt=0;
const TIMER_ACTIVE_USER_KEY='studyhub_active_timer_user_v1';
const TIMER_COMMAND_KEY='studyhub_timer_command_v1';
function timerStorageKey(){return `studyhub_timer_v1_${user?.id||'guest'}`}
function persistTimer(force=false){try{if(!user)return;localStorage.setItem(TIMER_ACTIVE_USER_KEY,user.id);if(!force&&Date.now()-timerPersistAt<5000)return;timerPersistAt=Date.now();localStorage.setItem(timerStorageKey(),JSON.stringify(timer))}catch(e){console.warn('Timer state could not be saved locally.',e)}}
function restoreTimer(){try{if(!user)return;localStorage.setItem(TIMER_ACTIVE_USER_KEY,user.id);const raw=localStorage.getItem(timerStorageKey());if(!raw)return;const saved=JSON.parse(raw);if(!saved||!Number.isFinite(Number(saved.total)))return;timer={...timer,...saved};if(timer.running&&timer.deadline){timer.remaining=Math.max(0,(timer.deadline-Date.now())/1000);if(timer.remaining<=0){timer.running=false;timer.completionPending=timer.mode==='focus';timer.remaining=0}}else timer.running=false;}catch(e){console.warn('Timer state could not be restored.',e)}}
window.addEventListener('storage',e=>{
 if(!user)return;
 if(e.key===TIMER_STORAGE_KEY_FOR_USER()){
  try{const saved=JSON.parse(e.newValue||'null');if(!saved||!Number.isFinite(Number(saved.total)))return;timer={...timer,...saved};if(timer.running&&timer.deadline)timer.remaining=Math.max(0,(timer.deadline-Date.now())/1000);updateTimerDisplay(false)}catch(err){console.warn('Could not sync floating timer state.',err)}
 }
 if(e.key===TIMER_COMMAND_KEY&&e.newValue){try{const command=JSON.parse(e.newValue);if(command?.action==='log'&&command.id!==window.__studyHubLastTimerCommand){window.__studyHubLastTimerCommand=command.id;logTimer()}}catch(err){console.warn('Could not process floating timer command.',err)}}
});
function TIMER_STORAGE_KEY_FOR_USER(){return `studyhub_timer_v1_${user?.id||'guest'}`}
async function handleSession(session){
  if(!session?.user){
    ++authLoadId;user=null;profile=null;state=defaultState();activeSessionUserId=null;sessionLoadingUserId=null;
    showAuth();
    return;
  }
  if(session.user.id===activeSessionUserId){user=session.user;return}
  if(session.user.id===sessionLoadingUserId)return;
  const loadId=++authLoadId;sessionLoadingUserId=session.user.id;user=session.user;
  try{
    await Promise.all([loadProfile(),loadState()]);
    if(loadId!==authLoadId)return;
    restoreTimer();activeSessionUserId=user.id;showApp();
  }catch(e){
    console.error('StudyHub session setup failed:',e);
    if(loadId===authLoadId)showAuth('Could not load your account data. Check the Supabase tables, policies and setup guide. '+(e.message||''));
  }finally{if(sessionLoadingUserId===session.user.id)sessionLoadingUserId=null}
}
async function boot(){
  if(!supabase){showAuth('Supabase configuration is missing. Check js/config.js.');return}
  // Supabase holds an internal auth lock while notifying listeners. Defer database
  // queries until the callback has returned to avoid lock contention/deadlocks.
  supabase.auth.onAuthStateChange((event,session)=>{
    if(event==='SIGNED_IN'||event==='INITIAL_SESSION'){
      queueMicrotask(()=>handleSession(session));
    }else if(event==='SIGNED_OUT'){ 
      queueMicrotask(()=>handleSession(null));
    }
  });
  const {data,error}=await supabase.auth.getSession();
  if(error){console.error(error);showAuth('Could not verify your session. Please refresh and sign in again.');return}
  await handleSession(data?.session||null);

  if (error) {
    console.error("FUNCTION ERROR:", error);
  
    if (error.context) {
      const details = await error.context.clone().text();
      console.error("ACTUAL SERVER RESPONSE:", details);
    }
  
    throw error;
  }
}
