$('#authForm').addEventListener('submit',async e=>{e.preventDefault();if(!supabase){$('#authMessage').textContent='Supabase is not configured.';return}const username=$('#authUsername').value.trim().toLowerCase(),password=$('#authPassword').value,confirm=$('#confirmPassword').value;const valid=/^[a-z0-9_.-]{3,20}$/.test(username);if(!valid){$('#authMessage').textContent='Username must be 3–20 characters: letters, numbers, dots, underscores or hyphens.';return}if(password.length<8){$('#authMessage').textContent='Use a password with at least 8 characters.';return}if(authMode==='signup'&&password!==confirm){$('#authMessage').textContent='The passwords do not match.';return}const b=$('#authSubmit');b.disabled=true;$('#authMessage').textContent=authMode==='signup'?'Creating your account…':'Signing in…';
  // Supabase Auth uses email/password internally. This reserved, non-deliverable address keeps the public UI username-only.
  const internalEmail=`${username}@accounts.studyhub.invalid`;
  try{let result;if(authMode==='signup'){result=await supabase.auth.signUp({email:internalEmail,password,options:{data:{username,display_name:username}}});if(!result.error&&!result.data.session){$('#authMessage').textContent='Account created. If confirmation is enabled, turn off email confirmations in Supabase because this username-only account has no email inbox.';return}}else{result=await supabase.auth.signInWithPassword({email:internalEmail,password})}if(result.error)throw result.error;$('#authMessage').textContent='Signed in. Loading your StudyHub…'}catch(err){$('#authMessage').textContent=err.message||'Authentication failed. Please try again.'}finally{b.disabled=false}
});
async function signOut(){
  if(!supabase)return;
  const signedOutUserId=user?.id;const {error}=await supabase.auth.signOut();
  if(error){toast('Could not sign out: '+error.message);return}
  authLoadId++;
  try{if(localStorage.getItem(TIMER_ACTIVE_USER_KEY)===signedOutUserId)localStorage.removeItem(TIMER_ACTIVE_USER_KEY)}catch{}
  user=null;profile=null;state=defaultState();
  showAuth();
}
