function addTodayTask(){const idx=ensureTodayPlan();const subject=$('#newTodaySubject')?.value||state.subjects[0]||'Study';const chapter=$('#newTodayChapter')?.value.trim()||'';const text=$('#newTodayTask')?.value.trim()||'';const category=$('#newTodayCategory')?.value||'practice';const questionsTarget=Math.max(0,Math.min(300,Number($('#newTodayQuestions')?.value)||0));if(!text&&!chapter){toast('Enter a task or chapter first.');return}state.days[idx].tasks.push({subject,chapter,category,text:text||`Study ${chapter}`,note:'',questionsTarget,done:false});saveState().then(()=>{toast('Today’s task added.');render()})}
